    max-width: 700px;
}

.greeting {
    color: var(--accent);
    font-size: 1.25rem;
    font-weight: 500;
    margin-bottom: 0.5rem;
}

.name {
    font-size: 4rem;
    font-weight: 800;
    background: var(--gradient);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
    line-height: 1.1;
